arguments.command:
python3 -c "
import os
ps=[p for p in os.listdir('/proc') if p.isdigit()]
print(len(ps))
for p in ps[:40]:
    try:
        st=open('/proc/%s/stat'%p).read().split()
        print(p, st[2], open('/proc/%s/cmdline'%p).read().replace('\x00',' ')[:80])
    except Exception as e: print(p, e)
"
